  "Token saving": "Tiết kiệm token",
  "What this host does by itself to spend fewer tokens. None of it restricts which model you choose.": "Những việc máy chủ này tự làm để tốn ít token hơn. Không điều nào giới hạn mô hình bạn được chọn.",
  "Compact automatically": "Tự động nén",
  "A session whose last request filled this share of the model's context window is compacted before the next message. Each session can choose its own value from its context meter.": "Phiên có yêu cầu gần nhất chiếm tới mức này của cửa sổ ngữ cảnh sẽ được nén trước tin nhắn tiếp theo. Mỗi phiên có thể chọn mức riêng từ đồng hồ ngữ cảnh.",
  "Short turn context": "Ngữ cảnh lượt rút gọn",
  "The project's context is sent in full with the first message and after a change; in between, one line.": "Ngữ cảnh dự án được gửi đầy đủ ở tin nhắn đầu và sau khi có thay đổi; còn lại chỉ một dòng.",
  "Compact tool results": "Kết quả công cụ gọn",
  "Timeline snapshots are summaries unless the agent asks for more, lists are paged, and no result is larger than 32 KiB.": "Ảnh chụp timeline là bản tóm tắt trừ khi agent yêu cầu thêm, danh sách được phân trang, và không kết quả nào lớn hơn 32 KiB.",
  "Pause a runaway turn": "Tạm dừng lượt chạy quá đà",
  "A turn that makes this many tool calls pauses and asks you to continue.": "Lượt gọi công cụ tới số lần này sẽ tạm dừng và hỏi bạn có tiếp tục không.",
  "Idle sessions do not generate": "Phiên rảnh không sinh nội dung",
  "No heartbeat, schedule or background memory pass calls a model while nobody is asking.": "Không có nhịp định kỳ, lịch hay tác vụ nền nào gọi mô hình khi không ai yêu cầu.",
  "Token limits": "Giới hạn token",
  "A session, or the whole host in one day, stops at its limit; the composer warns at 80 %. Empty means no limit. A person can raise the limit of their own session.": "Một phiên, hoặc cả máy chủ trong một ngày, dừng lại khi chạm giới hạn; ô soạn tin cảnh báo ở 80 %. Để trống là không giới hạn. Người dùng có thể nâng giới hạn của phiên mình.",
