  "This build has no update feed. Install a newer version by downloading it.": "Bản dựng này không có nguồn cập nhật. Hãy tải phiên bản mới hơn về để cài đặt.",
  "This build is not signed, so it cannot install an update by itself. A new version is downloaded and verified; open the downloaded file to install it.": "Bản dựng này chưa được ký nên không thể tự cài bản cập nhật. Phiên bản mới được tải về và xác minh; hãy mở tệp đã tải để cài đặt.",
