  "The host proved its identity. A device that is already trusted on that host now shows a six-digit code for this request.": "Host đã chứng minh danh tính. Một thiết bị đã được tin cậy trên host đó hiện đang hiển thị mã sáu chữ số cho yêu cầu này.",
  "Verification code": "Mã xác minh",
