  "{model} cannot speak in the voice of a sample. Choose a voice model that can in Settings ▸ Model routing.": "{model} không nói được bằng giọng của một mẫu. Hãy chọn mô hình giọng nói làm được việc này trong Cài đặt ▸ Định tuyến mô hình.",
