  "This computer has Tailscale turned off, so a phone cannot reach it. Turn Tailscale on in JAgentChill on the computer, then make a new pairing link.": "Máy tính này đang tắt Tailscale nên điện thoại không kết nối tới được. Hãy bật Tailscale trong JAgentChill trên máy tính rồi tạo liên kết ghép nối mới.",
  "Tailscale is how your phone reaches this computer from anywhere, with no server in between. Sign in to Tailscale on this computer, then pair your phone.": "Tailscale là đường để điện thoại kết nối tới máy tính này từ bất cứ đâu, không qua máy chủ trung gian nào. Hãy đăng nhập Tailscale trên máy tính này rồi ghép nối điện thoại.",
