  "Sign in with your Tailscale account so your phone can reach this computer.": "Đăng nhập bằng tài khoản Tailscale để điện thoại kết nối được tới máy tính này.",
  "Tailscale is off. Only this computer can use JAgentChill until you turn it on.": "Tailscale đang tắt. Chỉ máy tính này dùng được JAgentChill cho tới khi bạn bật lên.",
